//   заметка QA-AUTO-e0026a-…; хвост: «ממתינה לאישור» → отклоняется, утверждённый → доводится до «סופקה» (разрешение 18.10).
import { test, expect, Page } from '@playwright/test';
import { mockAi } from '../_ai-mock';
import * as path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/admin.json') });

const CUSTOMER = 'test';
const removeBtn = (page: Page, name: string) => page.getByRole('button', { name: `הסרת שורה — ${name}`, exact: true });
const plusBtn = (page: Page, name: string) => page.getByRole('button', { name: `הוספת יחידה — ${name}`, exact: true });
const qtyOf = (page: Page, name: string) => plusBtn(page, name).locator('xpath=..').locator('span[aria-live="polite"]');
const SOLD_OUT_DRAFT = 'אזל מהמלאי — לא ייכנס להזמנה.';

/** Остаток «במלאי» и «זמינות» товара в /catalog (только чтение). */
async function catalogInfo(page: Page, name: string) {
  await page.goto('/catalog');
  await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('textbox', { name: /חיפוש מוצר/ }).fill(name);
  const stockBtn = page.getByRole('button', { name: `קליטת מלאי — ${name}`, exact: true });
  await expect(stockBtn, `товар «${name}» в каталоге`).toBeVisible({ timeout: 20_000 });
  await expect(page.locator('button[aria-current]').filter({ hasText: /^הכל1$/ }), 'поиск сузил список до 1 товара').toBeVisible({ timeout: 20_000 });
  const stock = Number((await stockBtn.innerText()).replace(/[^\d.-]/g, '') || 0);
  const unavailable = (await page.locator('button[aria-current]').filter({ hasText: /^לא זמינים1$/ }).count()) === 1;
  return { stock, available: !unavailable };
}

/** Окно теста не может сохранить заказ: create_customer_order блокируется и считается. */
async function blockSave(page: Page) {
  const calls: string[] = [];
  await page.route('**/rest/v1/rpc/create_customer_order**', (r) => { calls.push(r.request().url()); return r.abort(); });
  return calls;
}

async function readMessage(page: Page, text: string) {
  await page.goto('/orders/new');
  await expect(page.getByRole('heading', { level: 1, name: 'הזמנה מהודעה' })).toBeVisible({ timeout: 30_000 });
  const customer = page.getByRole('combobox');
  await customer.fill(CUSTOMER);
  await page.getByRole('option').filter({ has: page.getByText(CUSTOMER, { exact: true }) }).first().click();
  await expect(page.getByText('איש קשר')).toBeVisible();
  await page.getByRole('textbox', { name: 'הודעת ההזמנה' }).fill(text);
  const read = page.getByRole('button', { name: 'קריאת הודעה' });
  await expect(read).toBeEnabled();
  const [resp] = await Promise.all([
    page.waitForResponse((r) => r.url().includes('/functions/v1/order-photo') && r.request().method() === 'POST', { timeout: 90_000 }),
    read.click(),
  ]);
  const body = await resp.json().catch(() => null);
  expect(resp.status(), 'order-photo HTTP 200').toBe(200);
  expect(body?.ok, `order-photo ok:true (code=${body?.code ?? '—'})`).toBe(true);
  await expect(page.getByText(/לא הצלחנו לקרוא את הרשימה/)).toHaveCount(0);
  return body;
}

test.describe('orders — «הזמנה מהודעה»: מוצר עם «זמינות» דלוקה נכנס לטיוטה בכל מלאי (#e7e338, זמני)', () => {
  test('«2 מצית קליפט, 1 דוידוף גולד» — order-photo ok, טיוטה 2 שורות בכמויות שבהודעה, בלי «אזל מהמלאי»/«נותרו», «+» מעבר למלאי; בלי שמירה #e7e338 @desktop @orders @ai @prod-safe', async ({ page }) => {
    test.setTimeout(180_000);
    const items = [{ name: 'מצית קליפט', asked: 2 }, { name: 'דוידוף גולד', asked: 1 }];
    const info: Record<string, { stock: number; available: boolean }> = {};
    for (const it of items) info[it.name] = await catalogInfo(page, it.name);
    for (const it of items) expect(info[it.name].available, `«${it.name}»: «זמינות» вкл. (предусловие)`).toBe(true);
    test.info().annotations.push({ type: 'stock', description: items.map((i) => `${i.name}: במלאי ${info[i.name].stock}`).join('; ') });

    const saves = await blockSave(page);
    await readMessage(page, '2 מצית קליפט, 1 דוידוף גולד');

    await expect(page.locator('button[aria-label^="הסרת שורה — "]'), 'черновик — 2 строки').toHaveCount(2, { timeout: 15_000 });
    for (const it of items) {
      await expect(removeBtn(page, it.name), `строка «${it.name}»`).toBeVisible();
      await expect(qtyOf(page, it.name), `«${it.name}»: кол-во как в сообщении`).toHaveText(String(it.asked));
    }
    await expect(page.getByText(SOLD_OUT_DRAFT), 'нет «אזל מהמלאי — לא ייכנס להזמנה.»').toHaveCount(0);
    await expect(page.getByText(/אזל מהמלאי · לא ניתן להוסיף להזמנה/)).toHaveCount(0);
    await expect(page.getByText(/— נותרו\s*\d+\s*בלבד/), 'кол-во не урезано по остатку').toHaveCount(0);

    // «+» без потолка остатка: доводим кол-во товара с меньшим остатком до «остаток + 1» (не больше 20 кликов).
    const low = [...items].sort((a, b) => info[a.name].stock - info[b.name].stock)[0];
    const target = Math.max(info[low.name].stock + 1, low.asked + 1);
    const clicks = Math.min(target - low.asked, 20);
    for (let i = 0; i < clicks; i++) await plusBtn(page, low.name).click();
    await expect(qtyOf(page, low.name), `«${low.name}»: кол-во ${low.asked + clicks} (остаток ${info[low.name].stock})`).toHaveText(String(low.asked + clicks));
    await expect(plusBtn(page, low.name), `«${low.name}»: «+» не заблокирован`).toBeEnabled();
    await expect(page.getByText(SOLD_OUT_DRAFT)).toHaveCount(0);
    await expect(page.getByRole('button', { name: /^רישום ההזמנה/ }), 'кнопка сохранения доступна (не нажимаем)').toBeEnabled();

    expect(saves, 'заказ не сохранялся').toHaveLength(0);
  });

  test('מוצר עם «זמינות» כבויה («נקש») — בטיוטה «אזל מהמלאי — לא ייכנס להזמנה.», בלי «+»; בלי שמירה #e7e338 @desktop @orders @ai @prod-safe', async ({ page }) => {
    test.setTimeout(150_000);
    const name = 'נקש';
    const info = await catalogInfo(page, name);
    test.skip(info.available, `«${name}» сейчас «זמינות» вкл. — нужен товар с выключенной «זמינות»`);

    const saves = await blockSave(page);
    await readMessage(page, `1 ${name}`);

    await expect(removeBtn(page, name), `строка «${name}» в черновике`).toBeVisible({ timeout: 15_000 });
    await expect(page.getByText(SOLD_OUT_DRAFT), 'пометка «אזל מהמלאי — לא ייכנס להזמנה.»').toBeVisible();
    await expect(plusBtn(page, name), 'у недоступного товара нет выбора кол-ва').toHaveCount(0);
    expect(saves, 'заказ не сохранялся').toHaveLength(0);
  });
});

// ---------- #e0026a: статус заказа из «הזמנה מהודעה» (распознавание подменено) ----------
const PRODUCT = 'מצית קליפט';
const header = (page: Page) => page.getByRole('heading', { level: 1 }).locator('..');
const pickingBtn = (page: Page, no: string) => page.getByRole('button', { name: new RegExp(`^הזמנה #${no} `) });

/** id товара из /catalog (клик по названию → /catalog/<id>/edit), без изменений. */
async function productId(page: Page, name: string) {
  await page.goto('/catalog');
  await expect(page.getByRole('heading', { level: 1, name: 'קטלוג וניהול' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('textbox', { name: /חיפוש מוצר/ }).fill(name);
  await expect(page.getByRole('button', { name: `קליטת מלאי — ${name}`, exact: true })).toBeVisible({ timeout: 20_000 });
  await page.getByRole('button', { name, exact: true }).first().click();
  await expect(page).toHaveURL(/\/catalog\/[0-9a-f-]{36}\/edit$/, { timeout: 20_000 });
  const id = page.url().match(/\/catalog\/([0-9a-f-]{36})\/edit$/)![1];
  await page.getByRole('button', { name: 'ביטול', exact: true }).click();
  return id;
}

/** «הזמנה מהודעה» с подменённым распознаванием (1 × «מצית קליפט») → «רישום ההזמנה»; возвращает номер и адрес карточки. */
async function saveFromMessage(page: Page, note: string) {
  const id = await productId(page, PRODUCT);
  const ai = await mockAi(page, 'order-photo', 200, { ok: true, lines: [{ text: `1 ${PRODUCT}`, product_id: id, qty: 1 }] });
  await page.goto('/orders/new');
  await expect(page.getByRole('heading', { level: 1, name: 'הזמנה מהודעה' })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('combobox').fill(CUSTOMER);
  await page.getByRole('option').filter({ has: page.getByText(CUSTOMER, { exact: true }) }).first().click();
  await expect(page.getByText('איש קשר')).toBeVisible();
  await page.getByRole('textbox', { name: 'הודעת ההזמנה' }).fill(`1 ${PRODUCT}`);
  await page.getByRole('button', { name: 'קריאת הודעה' }).click();
  await expect(removeBtn(page, PRODUCT), 'черновик — строка «מצית קליפט»').toBeVisible({ timeout: 20_000 });
  await expect(page.locator('button[aria-label^="הסרת שורה — "]')).toHaveCount(1);
  await expect(qtyOf(page, PRODUCT)).toHaveText('1');
  expect(ai.hits, 'распознавание — один подменённый вызов').toBe(1);
  await page.getByRole('textbox', { name: /הערה להזמנה/ }).fill(note);
  const save = page.getByRole('button', { name: /^רישום ההזמנה/ });
  await expect(save).toBeEnabled({ timeout: 20_000 });
  const [resp] = await Promise.all([
    page.waitForResponse((r) => r.url().includes('/rpc/create_customer_order'), { timeout: 30_000 }),
    save.click(),
  ]);
  expect(resp.status(), 'create_customer_order').toBeLessThan(300);
  await page.waitForURL(/\/orders\/[0-9a-f-]{36}$/, { timeout: 30_000 });
  const h1 = page.getByRole('heading', { level: 1, name: /^הזמנה #\d+$/ });
  await expect(h1).toBeVisible({ timeout: 30_000 });
  const no = (await h1.innerText()).match(/#(\d+)/)![1];
  test.info().annotations.push({ type: 'test-data', description: `заказ #${no} (test, ${PRODUCT} ×1, ${note})` });
  expect(ai.hits, 'других вызовов AI не было').toBe(1);
  return { no, url: page.url() };
}

async function expectPending(page: Page) {
  await expect(header(page), 'статус «ממתינה לאישור»').toContainText('ממתינה לאישור', { timeout: 20_000 });
  await expect(header(page)).not.toContainText('אושרה');
  await expect(page.getByRole('button', { name: 'אישור הזמנה' })).toBeVisible();
  await expect(page.getByRole('button', { name: 'דחייה', exact: true })).toBeVisible();
  await expect(page.getByRole('button', { name: 'עריכה', exact: true })).toBeVisible();
}

async function openPicking(page: Page) {
  await page.goto('/warehouse/picking');
  await expect(page.getByRole('heading', { level: 1, name: 'ליקוט וניתוב' })).toBeVisible({ timeout: 30_000 });
  await expect(page.getByText(/הזמנות ממתינות לליקוט|אין הזמנות/).first()).toBeVisible({ timeout: 30_000 });
}

async function reject(page: Page, url: string, no: string) {
  await page.goto(url);
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${no}` })).toBeVisible({ timeout: 30_000 });
  await page.getByRole('button', { name: 'דחייה', exact: true }).click();
  const dlg = page.getByRole('dialog');
  await expect(dlg.getByRole('heading', { name: `דחיית הזמנה #${no}` })).toBeVisible();
  await dlg.getByRole('textbox', { name: 'סיבת הדחייה *' }).fill('QA-AUTO cleanup e0026a');
  await dlg.getByRole('button', { name: 'דחה הזמנה' }).click();
  await expect(header(page)).toContainText('נדחתה', { timeout: 20_000 });
}

/** Уборка хвоста: «ממתינה לאישור» → отклонить; утверждённый → довести до «סופקה». */
async function tidy(page: Page, o?: { no: string; url: string }) {
  if (!o) return;
  await page.goto(o.url);
  await expect(page.getByRole('heading', { level: 1, name: `הזמנה #${o.no}` })).toBeVisible({ timeout: 30_000 });
  if (await page.getByRole('button', { name: 'דחייה', exact: true }).count()) return reject(page, o.url, o.no);
  for (const [step, done] of [['סמן כמוכנה למשלוח', 'מוכנה למשלוח'], ['סמן כיצאה למשלוח', 'בדרך ללקוח'], ['סמן כסופקה', 'סופקה']]) {
    const btn = page.getByRole('button', { name: step });
    if ((await btn.count()) && (await btn.isEnabled())) {
      await btn.click();
      await expect(header(page)).toContainText(done, { timeout: 20_000 });
    }
  }
}

test.describe('orders — «הזמנה מהודעה»: ההזמנה נשמרת «ממתינה לאישור», לליקוט רק אחרי אישור (#e0026a)', () => {
  const TS = Date.now().toString().slice(-6);
  let order: { no: string; url: string } | undefined;
  test.afterEach(async ({ page }) => {
    test.setTimeout(test.info().timeout + 90_000);
    try { await tidy(page, order); } finally { order = undefined; }
  });

  test('שמירה → «ממתינה לאישור» (לא «אושרה»), בלשונית «ממתינות לאישור», «אישור הזמנה»/«דחייה»/«עריכה», לא בליקוט; דחייה → «נדחתה» #e0026a @desktop @orders @data', async ({ page }) => {
    test.setTimeout(180_000);
    order = await saveFromMessage(page, `QA-AUTO-e0026a-R-${TS}`);
    await expectPending(page);

    await page.goto('/orders');
    await page.getByRole('button', { name: /^ממתינות לאישור\s*\d+$/ }).click();
    await expect(page.getByRole('button', { name: new RegExp(`^#${order.no} `) }), 'заказ во вкладке «ממתינות לאישור»').toBeVisible({ timeout: 30_000 });

    await openPicking(page);
    await expect(pickingBtn(page, order.no), 'до утверждения — не в очереди ליקוט').toHaveCount(0);

    await reject(page, order.url, order.no);
    await expect(page.getByRole('button', { name: 'אישור הזמנה' })).toHaveCount(0);
    order = undefined;
  });

  test('אישור → «אושרה · ממתינה לליקוט», בלי «דחייה»/«עריכה», מופיעה בליקוט; נסגרת עד «סופקה» #e0026a @desktop @orders @data', async ({ page }) => {
    test.setTimeout(240_000);
    order = await saveFromMessage(page, `QA-AUTO-e0026a-A-${TS}`);
    await expectPending(page);
    await openPicking(page);
    await expect(pickingBtn(page, order.no), 'до утверждения — не в очереди ליקוט').toHaveCount(0);

    await page.goto(order.url);
    await page.getByRole('button', { name: 'אישור הזמנה' }).click();
    const dlg = page.getByRole('dialog');
    await dlg.getByRole('textbox', { name: 'הערה (לא חובה)' }).fill(`QA-AUTO-e0026a-A-${TS}`);
    await dlg.getByRole('button', { name: 'אשר הזמנה' }).click();
    await expect(header(page)).toContainText('אושרה · ממתינה לליקוט', { timeout: 20_000 });
    await expect(page.getByRole('button', { name: 'דחייה', exact: true }), 'после утверждения отклонить нельзя').toHaveCount(0);
    await expect(page.getByRole('button', { name: 'עריכה', exact: true })).toHaveCount(0);

    await openPicking(page);
    await expect(pickingBtn(page, order.no), 'после утверждения — в очереди ליקוט').toBeVisible({ timeout: 30_000 });

    // Доведение до «סופקה» кнопками מפיץ (без עובד מחסן и без списания склада) — проверяется в afterEach (tidy).
    await tidy(page, order);
    await expect(header(page)).toContainText('סופקה');
    order = undefined;
  });
});
